    private static byte[] Block(string base64) => Convert.FromBase64String(base64);

    [Fact]
    public void WallThatTheCountedLayoutCannotDecode_IsDecodedBySearchingTheLayouts()
    {
        var block = Block(Wall430318);
        uint size = (uint)(block.Length - 16);

        Assert.Null(TfBlockDeserializer.ExtractCuttingElementIdsAndSteps(block, 0, size, 3524, out var counted));
        Assert.Null(counted);

        var steps = TfBlockDeserializer.ExtractCutOutStepsWithLayoutSearch(block, 0, size, 3524);
        Assert.Equal([((ushort)4137, 431198, true)], steps);
    }

    [Fact]
    public void PairStepAfterAVerticalExtensionStep_IsRecovered()
    {
        var block = Block(Wall493612);
        uint size = (uint)(block.Length - 16);

        Assert.Null(TfBlockDeserializer.ExtractCuttingElementIdsAndSteps(block, 0, size, 3524, out _));

        var steps = TfBlockDeserializer.ExtractCutOutStepsWithLayoutSearch(block, 0, size, 3524);
        Assert.Equal([((ushort)977, 495352, false)], steps);
    }

    [Theory]
    [InlineData(true, new[] { 20, 30 }, true)]     // every step names an element the host references
    [InlineData(true, new[] { 20 }, false)]        // a step names one it does not
    [InlineData(true, null, false)]                // no references to check the steps against
    [InlineData(false, new[] { 20 }, true)]        // steps of the first reading are not checked
    public void StepsOfTheLayoutSearch_AreKeptOnlyWhenTheHostReferencesEveryCutter(bool searched, int[]? references, bool kept)
    {
        var state = new RvtIO.Internal.ParsingState();
        state.HostCutOutSteps[10] = [(4137, 20, true), (977, 30, false)];
        if (searched) state.HostCutOutStepsFromLayoutSearch.Add(10);
        var host = new RvtIO.Model.Element { Id = 10, References = references?.ToList() };

        ElementBuilder.AttachFamilyCutGeometry(host, 10, state);

        Assert.Equal(kept, host.CutOutSteps != null);
    }

    [Fact]
    public void BlockThatIsNoHostBlock_HasNoSteps()
    {
        Assert.Null(TfBlockDeserializer.ExtractCutOutStepsWithLayoutSearch(new byte[40], 0, 24, 3524));
        var block = Block(Wall430318);
        block[^1] ^= 0xFF; // the footer no longer repeats the size
        Assert.Null(TfBlockDeserializer.ExtractCutOutStepsWithLayoutSearch(block, 0, (uint)(block.Length - 16), 3524));
    }
}
